import threading
from typing import TypeVar, Optional

T = TypeVar('T')

class SingleProducerSingleConsumerRingBuffer:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.buffer = [None] * capacity
        self.write_index = threading.Atomic(0)
        self.read_index = threading.Atomic(0)

    def push(self, item: T) -> bool:
        next_write_index = (self.write_index.load() + 1) % self.capacity
        if next_write_index != self.read_index.load():
            self.buffer[self.write_index.load()] = item
            self.write_index.store(next_write_index)
            return True
        else:
            return False  # Buffer is full

    def pop(self) -> Optional[T]:
        if self.write_index.load() != self.read_index.load():
            item = self.buffer[self.read_index.load()]
            self.read_index.store((self.read_index.load() + 1) % self.capacity)
            return item
        else:
            return None  # Buffer is empty

